import {calculate,parseReceipt} from './calc.mjs';
const $=s=>document.querySelector(s),money=n=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(n),colors=['#d9ceff','#fcdcb4','#c6e7e5','#f7cde2','#cedafa','#e6e6bc'];let people=[],items=[],seq=0,busy=false,previewUrl=null;const next=()=>String(++seq),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let calculation;
function amount(id){const n=Number($(id).value);return Number.isFinite(n)?Math.min(1000000000,Math.max(0,Math.round(n))):0}
function renderPeople(){$('#people-count').textContent=`${people.length} orang`;$('#people').innerHTML=people.map((p,i)=>`<span class="person"><span class="avatar" style="--person-color:${colors[i%colors.length]}">${esc(p.name.slice(0,1).toUpperCase())}</span>${esc(p.name)}<button data-remove-person="${p.id}" aria-label="Hapus ${esc(p.name)}">×</button></span>`).join('')}
function renderItems(){$('#item-count').textContent=`${items.length} item`;$('#items').innerHTML=items.length?items.map(it=>`<article class="item" data-id="${it.id}"><div class="item-fields"><label>Nama pesanan<input data-field="name" value="${esc(it.name)}" placeholder="Contoh: Es kopi susu" maxlength="100"></label><label>Total harga (Rp)<input data-field="price" type="number" min="0" max="1000000000" step="1" value="${it.price}"></label><button class="delete-item" data-delete="${it.id}" aria-label="Hapus ${esc(it.name)||'item'}">×</button></div><div class="assignments">${people.map(p=>`<button class="assign" data-owner="${p.id}" aria-pressed="${it.owners.includes(p.id)}">${esc(p.name)}</button>`).join('')}${people.length>1?'<button class="assign all" data-all="true">Semua</button>':''}</div><p class="assign-note">${!people.length?'Tambahkan nama teman di atas.':!it.owners.length?'Belum dipilih punya siapa':it.owners.length===1?'Untuk sendiri':`Dibagi rata ${it.owners.length} orang`}</p></article>`).join(''):'<p class="empty-items">Belum ada pesanan.<br>Upload struk atau tambahkan item pertama.</p>'}
function update(){const tax=amount('#tax'),service=amount('#service'),discount=amount('#discount');calculation=calculate(people,items,tax,service,discount);const c=calculation;$('#grand-total').textContent=money(c.net);$('#subtotal').textContent=money(c.subtotal);$('#extras').textContent=money(tax+service);$('#discount-total').textContent='− '+money(discount);$('#results').innerHTML=people.length?people.map((p,i)=>`<div class="result"><div class="who"><span class="avatar" style="--person-color:${colors[i%colors.length]}">${esc(p.name[0].toUpperCase())}</span><span class="result-name">${esc(p.name)}<small>${items.filter(it=>it.owners.includes(p.id)).length} pesanan</small></span></div><strong>${c.valid?money(c.shares[i]):'—'}</strong></div>`).join(''):'<p class="summary-empty">Tambahkan teman dan pesanan untuk mulai menghitung.</p>';$('#unassigned').textContent=c.net<0?'Diskon tidak boleh melebihi subtotal + pajak + service.':c.unassigned?`${c.unassigned} item belum dibagi. Pilih nama pada setiap pesanan.`:items.some(it=>!it.name.trim())?'Lengkapi nama semua pesanan.':c.subtotal===0&&items.length?'Isi harga pesanan untuk menghitung.':'';const check=$('#bill-total').value;$('#reconcile').textContent=check!==''?(Math.round(Number(check))===c.net?'✓ Total cocok dengan struk.':`Selisih ${money(Math.abs(Math.round(Number(check))-c.net))} dari total struk. Periksa item dan biaya.`):'';$('#copy').disabled=!c.valid;$('#copy-status').textContent=''}
function render(){renderPeople();renderItems();update()}
$('#person-form').addEventListener('submit',e=>{e.preventDefault();const input=$('#person-name'),name=input.value.trim();if(!name)return;if(people.some(p=>p.name.toLowerCase()===name.toLowerCase())){input.setCustomValidity('Nama ini sudah ada. Pakai nama yang berbeda ya.');input.reportValidity();return}people.push({id:next(),name});input.value='';render();input.focus()});$('#person-name').addEventListener('input',()=>$('#person-name').setCustomValidity(''));
$('#people').addEventListener('click',e=>{const b=e.target.closest('[data-remove-person]');if(!b)return;people=people.filter(p=>p.id!==b.dataset.removePerson);items.forEach(i=>i.owners=i.owners.filter(id=>id!==b.dataset.removePerson));render()});
$('#add-item').addEventListener('click',()=>{items.push({id:next(),name:'',price:0,owners:[]});renderItems();update();$('#items .item:last-child input').focus()});
$('#items').addEventListener('input',e=>{if(!e.target.dataset.field)return;const it=items.find(i=>i.id===e.target.closest('.item').dataset.id);if(e.target.dataset.field==='name')it.name=e.target.value;else it.price=Math.min(1000000000,Math.max(0,Math.round(Number(e.target.value)||0)));update()});
$('#items').addEventListener('click',e=>{const a=e.target.closest('.item');if(!a)return;const it=items.find(i=>i.id===a.dataset.id),b=e.target.closest('button');if(!b)return;if(b.dataset.delete)items=items.filter(i=>i.id!==it.id);else if(b.dataset.owner){const id=b.dataset.owner;it.owners=it.owners.includes(id)?it.owners.filter(v=>v!==id):[...it.owners,id]}else if(b.dataset.all)it.owners=people.map(p=>p.id);renderItems();update()});
for(const id of ['tax','service','discount','bill-total'])$('#'+id).addEventListener('input',update);
$('#demo').addEventListener('click',()=>{if(items.length&&!confirm('Ganti pesanan dan nama saat ini dengan contoh?'))return;people=[{id:next(),name:'Kamu'},{id:next(),name:'Nadia'},{id:next(),name:'Dimas'}];items=[{id:next(),name:'Nasi goreng kampung',price:38000,owners:[people[0].id]},{id:next(),name:'Chicken katsu bowl',price:42000,owners:[people[1].id]},{id:next(),name:'Aglio olio',price:45000,owners:[people[2].id]},{id:next(),name:'Truffle fries · sharing',price:35000,owners:people.map(p=>p.id)}];$('#tax').value=16000;$('#service').value=8000;$('#discount').value=0;$('#bill-total').value=184000;$('#image-wrap').hidden=true;$('#raw-wrap').hidden=true;$('#ocr-status').textContent='Ini data contoh. Coba pilih nama pada setiap pesanan.';render()});
function summary(){return ['PATUNGAN',...items.map(i=>`${i.name}: ${money(i.price)} (${people.filter(p=>i.owners.includes(p.id)).map(p=>p.name).join(', ')})`),'',`Subtotal: ${money(calculation.subtotal)}`,`Pajak: ${money(amount('#tax'))}`,`Service: ${money(amount('#service'))}`,`Diskon: ${money(amount('#discount'))}`,`TOTAL: ${money(calculation.net)}`,'',...people.map((p,i)=>`${p.name}: ${money(calculation.shares[i])}`)].join('\n')}
$('#copy').addEventListener('click',async()=>{if(!calculation.valid)return;try{await navigator.clipboard.writeText(summary());$('#copy-status').textContent='Tersalin! Tinggal tempel di chat teman.'}catch{const t=document.createElement('textarea');t.value=summary();document.body.append(t);t.select();const ok=document.execCommand('copy');t.remove();$('#copy-status').textContent=ok?'Ringkasan tersalin.':'Tidak bisa menyalin di browser ini.'}});
function loadOcr(){if(window.Tesseract)return Promise.resolve(window.Tesseract);return new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/tesseract.js@5.1.1/dist/tesseract.min.js';s.onload=()=>resolve(window.Tesseract);s.onerror=()=>{s.remove();reject(new Error('Pembaca teks gagal dimuat. Periksa koneksi internet.'))};document.head.append(s)})}
async function readPhoto(file){if(!file||busy)return;if(!/^image\/(jpeg|png|webp)$/.test(file.type)){$('#ocr-status').textContent='Pilih foto JPG, PNG, atau WebP ya.';return}if(file.size>15*1024*1024){$('#ocr-status').textContent='Foto terlalu besar. Maksimal 15 MB.';return}if(items.length&&!confirm('Hasil bacaan akan mengganti pesanan dan biaya saat ini. Lanjutkan?'))return;busy=true;$('#photo').disabled=true;$('#demo').disabled=true;$('#progress').hidden=false;$('#progress').value=0;$('#ocr-status').textContent='Menyiapkan pembaca teks… pertama kali bisa sedikit lebih lama.';let worker;try{if(previewUrl)URL.revokeObjectURL(previewUrl);previewUrl=URL.createObjectURL(file);$('#receipt').src=previewUrl;$('#image-wrap').hidden=false;const T=await loadOcr();worker=await T.createWorker('eng',1,{logger:m=>{if(m.status==='recognizing text'){$('#ocr-status').textContent=`Membaca struk… ${Math.round(m.progress*100)}%`;$('#progress').value=m.progress}}});const result=await worker.recognize(file);$('#raw').value=result.data.text;$('#raw-wrap').hidden=false;const parsed=parseReceipt(result.data.text);if(!parsed.items.length){$('#ocr-status').textContent='Item belum berhasil dikenali. Coba foto lebih terang dan lurus, atau masukkan item manual. Pesanan sebelumnya tetap ada.';return}items=parsed.items.map(i=>({...i,id:next()}));$('#tax').value=parsed.tax;$('#service').value=parsed.service;$('#discount').value=parsed.discount;$('#bill-total').value=parsed.total??'';$('#ocr-status').textContent=`${items.length} calon item terbaca. Cocokkan nama, harga total per baris, serta pajak dengan foto sebelum membagi.`;render()}catch(err){$('#ocr-status').textContent='Foto belum berhasil dibaca. Pastikan internet aktif dan foto jelas, lalu upload ulang. Kamu tetap bisa input manual.'}finally{if(worker)await worker.terminate().catch(()=>{});busy=false;$('#photo').disabled=false;$('#demo').disabled=false;$('#progress').hidden=true;$('#photo').value=''}}
$('#photo').addEventListener('change',e=>readPhoto(e.target.files[0]));const drop=$('#drop');drop.addEventListener('dragover',e=>{e.preventDefault();drop.classList.add('drag')});drop.addEventListener('dragleave',()=>drop.classList.remove('drag'));drop.addEventListener('drop',e=>{e.preventDefault();drop.classList.remove('drag');readPhoto(e.dataTransfer.files[0])});
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'get_bill_summary',description:'Read the current bill, assignment status, and calculated shares. Does not modify the bill.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:input=>{if(!input||typeof input!=='object'||Object.keys(input).length)throw new Error('Expected an empty object');return {total:calculation.net,ready:calculation.valid,unassigned:calculation.unassigned,shares:people.map((p,i)=>({name:p.name,amount:calculation.valid?calculation.shares[i]:null}))}}})).catch(()=>{})}catch{}}
render();
